//FluidSync - web interface: HTTP parsing and replies (transport in FluidSyncHW.c, page in web/index.html)
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#include "FluidSyncWeb.h"
#include "FluidSyncHW.h"
#include "web_index.h" //WEB_INDEX_HTML[], generated by CMake from web/index.html

static void reply(int id, int status, const char *ctype, const char *body, int len){
    const char *reason = status == 200 ? "OK" : status == 400 ? "Bad Request" : status == 409 ? "Conflict" : "Not Found";
    char head[160];
    int n = snprintf(head, sizeof head,
                     "HTTP/1.0 %d %s\r\nContent-Type: %s\r\nContent-Length: %d\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n",
                     status, reason, ctype, len);
    if(hw_wifi_send(id, head, n)) hw_wifi_send(id, body, len);
    hw_wifi_close(id);
}

void web_reply_page(int id){
    reply(id, 200, "text/html", WEB_INDEX_HTML, sizeof WEB_INDEX_HTML);
}

void web_reply_text(int id, int status, const char *text){
    reply(id, status, "text/plain", text, strlen(text));
}

void web_reply_config(int id, const machine_config_t *cfg, int queue_len, int queue_max){
    char b[1024]; //worst case ~750 bytes: names are max 15 chars and never contain " or backslash
    int n = snprintf(b, sizeof b, "{\"q\":[%d,%d],\"l\":[", queue_len, queue_max);
    for(int i = 0; i < N_PUMPS && n < (int)sizeof b; i++){
        const liquid_cfg_t *l = &cfg->liquid[i];
        n += snprintf(b + n, sizeof b - n, "%s{\"n\":\"%s\",\"c\":\"#%06lx\"}",
                      i ? "," : "", l->name, (unsigned long)(l->color & 0xFFFFFF));
    }
    if(n < (int)sizeof b) n += snprintf(b + n, sizeof b - n, "],\"p\":[");
    for(int i = 0; i < CFG_N_PRESETS && n < (int)sizeof b; i++){
        const preset_cfg_t *p = &cfg->preset[i];
        n += snprintf(b + n, sizeof b - n, "%s{\"n\":\"%s\",\"ml\":%u,\"v\":[", i ? "," : "", p->name, p->volume_ml);
        for(int k = 0; k < N_PUMPS && n < (int)sizeof b; k++) n += snprintf(b + n, sizeof b - n, "%s%u", k ? "," : "", p->pct[k]);
        if(n < (int)sizeof b) n += snprintf(b + n, sizeof b - n, "]}");
    }
    if(n < (int)sizeof b) n += snprintf(b + n, sizeof b - n, "]}");
    if(n >= (int)sizeof b){ web_reply_text(id, 400, "Config too big"); return; } //cannot happen with the limits above
    reply(id, 200, "application/json", b, n);
}

//value of key in the query string q ("a=1&b=2"), URL-decoded. Length, or -1 if absent
static int qparam(const char *q, const char *key, char *out, int size){
    size_t kl = strlen(key);
    for(const char *p = q; p; p = strchr(p, '&') ? strchr(p, '&') + 1 : NULL){
        if(strncmp(p, key, kl) != 0 || p[kl] != '=') continue;
        p += kl + 1;
        int n = 0;
        while(*p && *p != '&' && n < size - 1){
            char c = *p++;
            if(c == '+') c = ' ';
            else if(c == '%' && isxdigit((unsigned char)p[0]) && isxdigit((unsigned char)p[1])){
                char h[3] = { p[0], p[1], 0 };
                c = (char)strtol(h, NULL, 16);
                p += 2;
            }
            out[n++] = c;
        }
        out[n] = 0;
        return n;
    }
    return -1;
}

static bool qint(const char *q, const char *key, long min, long max, int base, long *v){
    char s[12], *end;
    if(qparam(q, key, s, sizeof s) <= 0) return false;
    *v = strtol(s, &end, base);
    return *end == 0 && *v >= min && *v <= max;
}

//names are shown in HTML, JSON and on the TFT font: keep only safe printable ASCII
static void clean_name(char *dst, const char *src){
    int n = 0;
    for(; *src && n < CFG_NAME_LEN - 1; src++)
        if(*src >= 0x20 && *src < 0x7F && !strchr("\"\\<>&%,", *src)) dst[n++] = *src;
    dst[n] = 0;
}

void web_parse(const char *req, web_request_t *out){
    memset(out, 0, sizeof *out);
    if(strncmp(req, "GET /", 5) != 0) return; //WEB_NOT_FOUND

    char path[200];
    int n = 0;
    for(const char *p = req + 4; *p && *p != ' ' && *p != '\r' && n < (int)sizeof path - 1; p++) path[n++] = *p;
    path[n] = 0;
    char *q = strchr(path, '?');
    if(q) *q++ = 0;
    else q = path + n; //empty query

    char s[48];
    long v;
    if(strcmp(path, "/") == 0){
        out->type = WEB_PAGE;
    }else if(strcmp(path, "/cfg") == 0){
        out->type = WEB_CONFIG;
    }else if(strcmp(path, "/order") == 0){
        out->type = WEB_BAD;
        if(!qint(q, "p", 0, CFG_N_PRESETS - 1, 10, &v)) return;
        out->index = (int)v;
        out->type = WEB_ORDER;
    }else if(strcmp(path, "/liquid") == 0){
        out->type = WEB_BAD;
        if(!qint(q, "i", 0, N_PUMPS - 1, 10, &v)) return;
        out->index = (int)v;
        if(qparam(q, "n", s, sizeof s) < 0) return;
        clean_name(out->liquid.name, s);
        if(!out->liquid.name[0]) return;
        if(qparam(q, "c", s, sizeof s) != 6 || !qint(q, "c", 0, 0xFFFFFF, 16, &v)) return;
        out->liquid.color = (uint32_t)v;
        out->type = WEB_SET_LIQUID;
    }else if(strcmp(path, "/preset") == 0){
        out->type = WEB_BAD;
        if(!qint(q, "i", 0, CFG_N_PRESETS - 1, 10, &v)) return;
        out->index = (int)v;
        if(qparam(q, "n", s, sizeof s) < 0) return;
        clean_name(out->preset.name, s);
        if(!qint(q, "ml", CFG_MIN_ML, CFG_MAX_ML, 10, &v)) return;
        out->preset.volume_ml = (uint8_t)v;
        if(qparam(q, "v", s, sizeof s) < 0) return;
        char *p = s, *end;
        for(int k = 0; k < N_PUMPS; k++){ //"P1,P2,...,P6", each 0..100
            v = strtol(p, &end, 10);
            if(end == p || v < 0 || v > 100) return;
            out->preset.pct[k] = (uint8_t)v;
            p = end;
            if(k < N_PUMPS - 1){ if(*p != ',') return; p++; }
        }
        if(*p) return;
        out->type = WEB_SET_PRESET;
    }
}
